  "hooks": {
    "SessionStart": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "'<BUN>' '<RUNNER>' hook session-start # kiwi",
            "timeout": 30
          }
        ]
      },
      {
        "hooks": [
          {
            "type": "command",
            "command": "'<BUN>' '<RUNNER>' hook listen # kiwi",
