      {
        "hooks": [
          {
            "type": "command",
            "command": "'<BUN>' '<RUNNER>' hook listen # kiwi",
            "async": true,
            "asyncRewake": true,
            "timeout": 604860
          }
        ]
      }
    ],
    "Stop": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "'<BUN>' '<RUNNER>' hook stop # kiwi",
            "timeout": 30
          }
        ]
      },
      {
        "hooks": [
          {
            "type": "command",
            "command": "'<BUN>' '<RUNNER>' hook listen # kiwi",
            "async": true,
            "asyncRewake": true,
            "timeout": 604860
          }
        ]
      }
    ],
    "PermissionRequest": [
      {
        "matcher": "Bash|Edit|Write|MultiEdit|NotebookEdit|WebFetch|mcp__.*",
